22	const PROCESSING_FEE = 5;
23	const INITIAL_ASSESSMENT_SURCHARGE_RATE = 0.1;
24	
25	const BASE_PREMIUMS: Record<string, number | undefined> = {
26	  sword: 100,
27	  amulet: 60,
28	  staff: 80,
29	  potion: 40,
30	  rune: 25,
31	  moonstone: 25,
32	};
