34	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type] ?? 0;
35	
36	const CURSE_SURCHARGE_RATE = 0.5;
37	
38	/** Item-specific modifiers apply to the base premium of the affected item only. */
39	const itemSurchargesOf = (item: Item): number => {
40	  const basePremium = basePremiumOf(item);
41	  return item.cursed === true ? basePremium * CURSE_SURCHARGE_RATE : 0;
42	};
43	
44	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
45	const COMPONENT_BLOCK_SIZE = 3;
46	const COMPONENT_BLOCK_PREMIUM = 60;
47	
48	const isComponent = (item: Item): boolean => COMPONENT_TYPES.has(item.type);
49	
50	/** Splits items into the ones priced as type groups and the ones priced individually. */
51	const partitionComponents = (items: Item[]): { components: Item[]; mainItems: Item[] } => {
52	  const components: Item[] = [];
53	  const mainItems: Item[] = [];
54	  for (const item of items) {
55	    (isComponent(item) ? components : mainItems).push(item);
56	  }
57	  return { components, mainItems };
58	};
59	
60	const countByType = (items: Item[]): Map<string, number> => {
61	  const counts = new Map<string, number>();
62	  for (const item of items) {
63	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
64	  }
65	  return counts;
66	};
67	
68	/**
69	 * Components of one type form a "building block" only when there are exactly 3
70	 * of them; otherwise each is priced individually.
71	 */
72	const componentGroupPremium = (type: string, count: number): number =>
73	  count === COMPONENT_BLOCK_SIZE ? COMPONENT_BLOCK_PREMIUM : count * basePremiumOf({ type });
74	
75	const policyBasePremiumOf = (step: QuoteStep): number => {
76	  const { components, mainItems } = partitionComponents(step.items);
77	
78	  const mainItemsPremium = mainItems.reduce((sum, item) => sum + basePremiumOf(item), 0);
79	  const componentsPremium = [...countByType(components)].reduce(
80	    (sum, [type, count]) => sum + componentGroupPremium(type, count),
81	    0,
82	  );
83	  return mainItemsPremium + componentsPremium;
84	};
85	
86	/** Kept as an exact fraction — only the final premium is rounded. */
87	const premiumBeforeRounding = (step: QuoteStep): number => {
88	  const policyBasePremium = policyBasePremiumOf(step);
89	  const itemSurcharges = step.items.reduce((sum, item) => sum + itemSurchargesOf(item), 0);
90	  const initialAssessmentSurcharge = policyBasePremium * INITIAL_ASSESSMENT_SURCHARGE_RATE;
91	  return policyBasePremium + itemSurcharges + initialAssessmentSurcharge + PROCESSING_FEE;
92	};
93	
94	/** Rounded up, in the MHPCO's favour. */
95	const finalPremiumFor = (step: QuoteStep): number => Math.ceil(premiumBeforeRounding(step));
96	
97	export const runScenario = (scenario: Scenario): ScenarioOutput => ({
98	  results: scenario.steps.map((step) => ({ premium: finalPremiumFor(step) })),
99	});
